-- Database-level enforcement of the curated role list (contracts/roles.ts).
-- Application-level zod validation alone can be bypassed by direct writes.
ALTER TABLE `talents` ADD CONSTRAINT `chk_talent_role` CHECK (`role` IN ('Talent', 'Software Developer', 'Frontend Developer', 'Data Engineer', 'Data Analyst', 'UX Designer', 'Designer', 'Financial Analyst', 'Risk Analyst', 'HR & People Advisor', 'Mechatronics Technician', 'Electrician', 'Plumber', 'Carpenter', 'Welder', 'Chef', 'Chef & Kitchen Lead', 'Chef — company restaurant', 'Baker', 'Kitchen Assistant', 'Hospitality Worker', 'Nurse', 'Caregiver', 'Teacher', 'Accountant', 'Logistics Coordinator', 'Warehouse Worker', 'Forklift Operator', 'Driver', 'Mechanic', 'Cleaner', 'Retail Associate', 'Customer Service', 'Marketing Specialist', 'Translator', 'Agricultural Worker', 'Construction Worker'));
